{"version":"1.0","updateComponents":{"surfaceId":"team-settings","components":[{"id":"root","component":"Stack","gap":"lg","children":["appbar","content"]},{"id":"appbar","component":"AppBar","title":"Team settings","subtitle":{"@path":"/team/name"}},{"id":"content","component":"Stack","gap":"lg","style":{"padding":"$spacing.lg","maxWidth":"720px","width":"100%","marginHorizontal":"auto"},"children":["general_card","danger_card"]},{"id":"general_card","component":"Card","title":"General","description":"How your team appears across the workspace.","children":["general_form"]},{"id":"general_form","component":"Form","name":"teamGeneral","busy":{"@path":"/saving"},"on":{"submit":{"event":{"name":"saveTeamSettings","context":{"name":{"@path":"/team/name"},"slug":{"@path":"/team/slug"},"timezone":{"@path":"/team/timezone"}}}}},"children":["name_input","slug_input","slug_preview","tz_select","form_actions"]},{"id":"name_input","component":"Input","label":"Team name","name":"name","value":{"@path":"/team/name"},"checks":[{"condition":{"@call":"required","args":{"value":{"@path":"/team/name"}}},"message":"Enter a team name."},{"condition":{"@call":"length","args":{"value":{"@path":"/team/name"},"min":2,"max":48}},"message":"Use 2 to 48 characters."}]},{"id":"slug_input","component":"Input","label":"URL slug","name":"slug","value":{"@path":"/team/slug"},"checks":[{"condition":{"@call":"required","args":{"value":{"@path":"/team/slug"}}},"message":"Enter a URL slug."},{"condition":{"@call":"regex","args":{"value":{"@path":"/team/slug"},"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$"}},"message":"Use lowercase letters, numbers and single hyphens."},{"condition":{"@call":"length","args":{"value":{"@path":"/team/slug"},"min":3,"max":32}},"message":"Use 3 to 32 characters."}]},{"id":"slug_preview","component":"Text","variant":"muted","text":{"@call":"concat","args":{"values":["app.exponential.at/",{"@path":"/team/slug"}]}}},{"id":"tz_select","component":"Select","label":"Timezone","name":"ti